// asciiFold returns the ASCII characters r contributes to an identifier:
// the ASCII part of its NFKD decomposition, or "" — meaning r is dropped
// — for a rune that decomposes to nothing ASCII at all.
func asciiFold(r rune) string {
	i := sort.Search(len(asciiFoldRunes), func(i int) bool {
		return asciiFoldRunes[i] >= r
	})
	if i >= len(asciiFoldRunes) || asciiFoldRunes[i] != r {
		return ""
	}
	span := asciiFoldSpans[i]
	off := int(span >> 8)
	return asciiFoldData[off : off+int(span&0xff)]
}
